const rows = $input.all().map(i => i.json);
const now = new Date();
const supported = new Set(['fb','li','discord']);

const due = rows.filter(r => {
  const status = String(r.status || '').trim().toLowerCase();
  const channel = String(r.channel || '').trim().toLowerCase();
  const scheduleAt = r.schedule_at ? new Date(r.schedule_at) : null;
  const dueNow = scheduleAt && !isNaN(scheduleAt) ? scheduleAt <= now : false;
  return status === 'queued' && supported.has(channel) && dueNow;
});

// Normalise each row's fields for downstream uniformity.
const items = due.map(r => ({
  json: {
    post_id: String(r.post_id || '').trim(),
    channel: String(r.channel || '').trim().toLowerCase(),
    post_text: String(r.post_text || ''),
    schedule_at: r.schedule_at,
    rewrite_enabled: String(r.rewrite_enabled || '').toLowerCase() === 'true' || r.rewrite_enabled === true,
    row_number: r.row_number
  }
}));

return items;

const row = $input.first().json;

// Per-channel persona + length budget. Tune in this map to change the
// rewrite voice without touching the prompt scaffolding below.
const personas = {
  fb: {
    name: 'Facebook Page (business audience)',
    voice: 'conversational, accessible, slightly warmer than LinkedIn',
    length_target: '80-200 words',
    emoji_policy: '1-2 contextual emojis OK; never lead with one',
    cta_policy: 'soft CTA at the end is OK; no hard sell',
    formatting: 'short paragraphs, blank line between thoughts; no markdown'
  },
  li: {
    name: 'LinkedIn Company Page (professional audience)',
    voice: 'professional, insight-led, first-person plural',
    length_target: '180-400 words',
    emoji_policy: 'no emojis',
    cta_policy: 'end with a single clear CTA or question to drive comments',
    formatting: 'hook in first 2 lines (above-the-fold), short paragraphs, no markdown, line breaks for scanability'
  },
  discord: {
    name: 'Discord channel announcement (community audience)',
    voice: 'direct, casual, peer-to-peer',
    length_target: '1-3 short sentences',
    emoji_policy: '1 contextual emoji at the start is fine',
    cta_policy: 'optional link; otherwise none',
    formatting: 'Discord markdown supported (**bold**, *italic*, ` code `)'
  }
};

const persona = personas[row.channel] || personas.fb;
const sourceText = row.post_text;

const systemPrompt = `You are a social-media copy editor rewriting one source post for one specific channel. Your job is to keep the message identical but change the form so it fits the channel's audience and conventions.

Return ONLY a single JSON object, no prose, no code fences. Shape:
{
  "rewritten_text": "<the rewritten post — channel-appropriate length and voice>",
  "notes": "<one sentence on what you changed and why>"
}

Channel: ${persona.name}
- Voice: ${persona.voice}
- Length target: ${persona.length_target}
- Emoji policy: ${persona.emoji_policy}
- CTA policy: ${persona.cta_policy}
- Formatting: ${persona.formatting}

Rules:
- Preserve the post's core message + any URLs or @mentions exactly.
- Do not invent facts, numbers, names, or quotes that aren't in the source.
- If the source is already channel-appropriate, return it nearly unchanged (do not over-edit).
- Do not include hashtags unless they appear in the source.`;

const userPrompt = `Source post (channel-agnostic):\n"""\n${sourceText}\n"""\n\nRewrite for ${persona.name}.`;

const fullPrompt = `${systemPrompt}\n\n---\n\n${userPrompt}`;

// Default pass-through: if rewrite is disabled, _post_text_final == source.
return [{ json: { ...row, _post_text_final: sourceText, _gemini_prompt: fullPrompt } }];

const gemini = $input.first().json;
const raw = gemini?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { rewritten_text: '', notes: 'Model returned non-JSON; falling back to source.' };
}

const prev = $('Build Per-Channel Prompt').item.json;
const rewritten = (parsed.rewritten_text || '').trim();

// If rewrite returned empty, fall back to source — never post nothing.
const finalText = rewritten || prev.post_text;

return [{ json: {
  post_id: prev.post_id,
  channel: prev.channel,
  post_text: prev.post_text,
  schedule_at: prev.schedule_at,
  rewrite_enabled: prev.rewrite_enabled,
  row_number: prev.row_number,
  _post_text_final: finalText,
  _rewrite_notes: parsed.notes || ''
} }];

// Each item arrives here with the channel API's response body merged on top
// of the original work item. We extract a per-channel result_url + success
// signal so the Sheet update has uniform fields to write.

const items = $input.all().map(i => i.json);

const out = items.map(j => {
  const channel = j.channel;
  let success = false;
  let result_url = '';
  let error = '';

  if (channel === 'fb') {
    // FB Graph: success → { id: '<page_id>_<post_id>' }; failure → { error: { message: ... } }
    if (j.id && typeof j.id === 'string') {
      success = true;
      result_url = `https://www.facebook.com/${j.id}`;
    } else if (j.error) {
      error = j.error.message || JSON.stringify(j.error);
    } else {
      error = 'Unknown FB response shape';
    }
  } else if (channel === 'li') {
    // LinkedIn UGC: success → { id: 'urn:li:share:<id>' }; failure → { message: ..., status: 4xx }
    if (j.id && String(j.id).startsWith('urn:li:share:')) {
      success = true;
      const shareId = String(j.id).replace('urn:li:share:', '');
      result_url = `https://www.linkedin.com/feed/update/urn:li:share:${shareId}/`;
    } else if (j.message) {
      error = `LI ${j.status || ''}: ${j.message}`.trim();
    } else {
      error = 'Unknown LI response shape';
    }
  } else if (channel === 'discord') {
    // Discord webhook with ?wait=true: success → { id, channel_id, guild_id? }; failure → { message, code }
    if (j.id && j.channel_id) {
      success = true;
      result_url = j.guild_id
        ? `https://discord.com/channels/${j.guild_id}/${j.channel_id}/${j.id}`
        : `https://discord.com/channels/@me/${j.channel_id}/${j.id}`;
    } else if (j.message) {
      error = `Discord ${j.code || ''}: ${j.message}`.trim();
    } else {
      error = 'Unknown Discord response shape';
    }
  } else {
    error = `Unsupported channel: ${channel}`;
  }

  return { json: {
    post_id: j.post_id,
    channel,
    status: success ? 'posted' : 'failed',
    posted_at: new Date().toISOString(),
    result_url,
    error,
    _post_text_final: j._post_text_final,
    _rewrite_notes: j._rewrite_notes || ''
  } };
});

return out;
